package forth

import (
	"errors"
	"strconv"
	"strings"
)

func Forth(input []string) ([]int, error) {
	stack := []int{}
	dict := map[string][]string{} // lowercase name -> expanded token list

	for _, line := range input {
		tokens := strings.Fields(line)
		if len(tokens) == 0 {
			continue
		}
		if tokens[0] == ":" {
			// definition
			if len(tokens) < 3 || tokens[len(tokens)-1] != ";" {
				return nil, errors.New("invalid definition")
			}
			name := strings.ToLower(tokens[1])
			if isNumber(tokens[1]) {
				return nil, errors.New("word name cannot be a number")
			}
			body := tokens[2 : len(tokens)-1]
			// expand recursively against the current dictionary
			expanded, err := expand(body, dict)
			if err != nil {
				return nil, err
			}
			dict[name] = expanded
			continue
		}
		if err := exec(tokens, dict, &stack); err != nil {
			return nil, err
		}
	}
	return stack, nil
}
```

expand: for each token, if it's a number keep it. Otherwise look up the lowercase name in dict → append the expanded list. Otherwise keep it as-is (to be resolved at runtime, either as a built-in or as an error).

exec: for each token: if it's a number → push. Otherwise lowercase it: if it's in dict → exec the expansion. Otherwise if it's a built-in → apply. Otherwise error.

