func builtin(name string, stack *[]int) error {
	switch name {
	case "+", "-", "*", "/":
		if len(*stack) < 2 {
			return errors.New("insufficient values on the stack")
		}
		b, a := (*stack)[len(*stack)-1], (*stack)[len(*stack)-2]
		*stack = (*stack)[:len(*stack)-2]
		switch name {
		case "+": *stack = append(*stack, a+b)
		case "-": *stack = append(*stack, a-b)
		case "*": *stack = append(*stack, a*b)
		default:
			if b == 0 { return errors.New("division by zero") }
			*stack = append(*stack, a/b)
		}
	case "dup":
		if len(*stack) < 1 { return errors.New("empty stack") }
		*stack = append(*stack, (*stack)[len(*stack)-1])
	case "drop":
		if len(*stack) < 1 { return errors.New("empty stack") }
		*stack = (*stack)[:len(*stack)-1]
	case "swap":
		if len(*stack) < 2 { return errors.New("insufficient values on the stack") }
		n := len(*stack)
		(*stack)[n-1], (*stack)[n-2] = (*stack)[n-2], (*stack)[n-1]
	case "over":
		if len(*stack) < 2 { return errors.New("insufficient values on the stack") }
		*stack = append(*stack, (*stack)[len(*stack)-2])
	default:
		return errors.New("undefined word")
	}
	return nil
